`timescale 1ps / 1ps
//=============================================================================
// Testbench: puf_fleet_tb
// Purpose:   Feeds 128-bit challenges to all 5 cars' 32-bit Parallel
//            Arbiter PUFs simultaneously. Captures VCD waveforms exposing
//            the pre-arbiter race signals for lane 0 of Car 1 and Car 2,
//            and exports 128-bit challenges + 32-bit responses to CSV.
//
// Architectural Requirements:
//   - Challenge: 128 bits (applied once per CRP)
//   - Response:  32 bits per car (generated by 32 parallel arbiter lanes in 1 cycle)
//   - Timescale: 1ps/1ps
//
// Outputs:
//   1. puf_fleet_waveform.vcd — Exposes the pre-arbiter race signals
//      (car1_lane0_upper, car1_lane0_lower, car2_lane0_upper, car2_lane0_lower)
//      along with trigger, challenge, and responses for GTKWave visual proof.
//
//   2. ../data/puf_crp_export.csv — Challenge-Response Pairs for all 5 cars,
//      formatted for seamless consumption by the Python SNN pipeline.
//=============================================================================

module puf_fleet_tb;

    // ── Configuration Parameters ──────────────────────────────────────
    parameter N              = 128;    // Challenge width (bits)
    parameter RESP_BITS      = 32;     // Response width (parallel lanes)
    parameter NUM_CHALLENGES = 32;     // Number of challenge vectors to test
    parameter SETTLE_TIME    = 35000;  // Wait for 128-stage propagation (ps)
    parameter RESET_TIME     = 5000;   // Dead time between challenges (ps)

    // ── Stimulus Registers ────────────────────────────────────────────
    reg             trigger;
    reg  [N-1:0]    challenge;

    // ── 32-bit Response Wires ─────────────────────────────────────────
    wire [RESP_BITS-1:0] car1_response, car2_response, car3_response;
    wire [RESP_BITS-1:0] car4_response, car5_response;

    // ── Pre-Arbiter Race Wires (exposed for GTKWave visual proof) ─────
    // These capture the literal picosecond arrival times at the arbiter DFF inputs
    wire car1_lane0_upper, car1_lane0_lower;
    wire car2_lane0_upper, car2_lane0_lower;
    wire car3_lane0_upper, car3_lane0_lower;
    wire car4_lane0_upper, car4_lane0_lower;
    wire car5_lane0_upper, car5_lane0_lower;

    // ── Instantiate 5-Car Fleet (32-bit Parallel PUF) ─────────────────
    vehicle_fleet_puf #(
        .N         (N),
        .RESP_BITS (RESP_BITS)
    ) uut (
        .trigger          (trigger),
        .challenge        (challenge),

        .car1_response    (car1_response),
        .car2_response    (car2_response),
        .car3_response    (car3_response),
        .car4_response    (car4_response),
        .car5_response    (car5_response),

        .car1_lane0_upper (car1_lane0_upper),
        .car1_lane0_lower (car1_lane0_lower),
        .car2_lane0_upper (car2_lane0_upper),
        .car2_lane0_lower (car2_lane0_lower),
        .car3_lane0_upper (car3_lane0_upper),
        .car3_lane0_lower (car3_lane0_lower),
        .car4_lane0_upper (car4_lane0_upper),
        .car4_lane0_lower (car4_lane0_lower),
        .car5_lane0_upper (car5_lane0_upper),
        .car5_lane0_lower (car5_lane0_lower)
    );

    // ── VCD Waveform Dump ─────────────────────────────────────────────
    // Level 1 dumps all signals declared in puf_fleet_tb:
    // - car1_lane0_upper, car1_lane0_lower (Car 1 lane 0 pre-arbiter race)
    // - car2_lane0_upper, car2_lane0_lower (Car 2 lane 0 pre-arbiter race)
    // - car3/4/5 pre-arbiter race wires
    // - trigger, challenge[127:0]
    // - car1..5 32-bit response vectors
    initial begin
        $dumpfile("puf_fleet_waveform.vcd");
        $dumpvars(1, puf_fleet_tb);
    end

    // ── CSV File Handle & Analysis Counters ───────────────────────────
    integer csv_file;
    integer i;
    integer pair_idx_a, pair_idx_b;
    integer hd_bits;
    integer total_hd;
    integer pair_count;

    reg [RESP_BITS-1:0] xor_result;
    reg [RESP_BITS-1:0] responses [0:4];

    // Per-car response bias counters (total 1-bits)
    integer total_ones_car1, total_ones_car2, total_ones_car3;
    integer total_ones_car4, total_ones_car5;

    // ── Popcount function (count 1-bits in 32-bit word) ───────────────
    function integer count_ones;
        input [RESP_BITS-1:0] val;
        integer ci;
        begin
            count_ones = 0;
            for (ci = 0; ci < RESP_BITS; ci = ci + 1)
                count_ones = count_ones + val[ci];
        end
    endfunction

    // ── Main Stimulus Block ───────────────────────────────────────────
    initial begin
        trigger         = 1'b0;
        challenge       = {N{1'b0}};
        total_hd        = 0;
        pair_count      = 0;
        total_ones_car1 = 0;
        total_ones_car2 = 0;
        total_ones_car3 = 0;
        total_ones_car4 = 0;
        total_ones_car5 = 0;

        // ── Open CSV file for Python SNN pipeline export ──────────────
        csv_file = $fopen("../data/puf_crp_export.csv", "w");
        if (csv_file == 0) begin
            $display("");
            $display("[ERROR] Could not open ../data/puf_crp_export.csv for writing.");
            $finish;
        end

        // Header: 128-bit challenge (hex) and 32-bit responses (hex) for each car
        $fdisplay(csv_file, "challenge_hex,car1_vid101,car2_vid102,car3_vid103,car4_vid104,car5_vid105");
        $fflush(csv_file);

        // ── Console Banner ────────────────────────────────────────────
        $display("");
        $display("================================================================================");
        $display("       32-BIT PARALLEL ARBITER PUF FLEET SIMULATION (VEHICULAR EDGE NETWORK)");
        $display("       Architecture : 128-bit Challenge -> 32-bit Response (Parallel, 1 Cycle)");
        $display("       Fleet Size   : 5 Cars (VID 101-105) x 32 Parallel Lanes x 128 Delay Stages");
        $display("================================================================================");
        $display("");
        $display(" Challenge (hex)                 | Car 1    | Car 2    | Car 3    | Car 4    | Car 5");
        $display("---------------------------------|----------|----------|----------|----------|----------");

        // Allow initial settling
        #(RESET_TIME);

        // ── Sweep 32 Challenges ───────────────────────────────────────
        for (i = 0; i < NUM_CHALLENGES; i = i + 1) begin
            if (i == 0)
                challenge = 128'hA5A5_A5A5_A5A5_A5A5_A5A5_A5A5_A5A5_A5A5;
            else
                challenge = {challenge[126:0], challenge[127] ^ challenge[125] ^ challenge[100] ^ challenge[63]};

            // Deassert trigger and settle select lines
            trigger = 1'b0;
            #(RESET_TIME);

            // *** FIRE TRIGGER PULSE — starts the race across all 32 lanes simultaneously ***
            trigger = 1'b1;

            // Wait for 128-stage race to complete and arbiters to settle
            #(SETTLE_TIME);

            // Display results row
            $display(" %032h | %08h | %08h | %08h | %08h | %08h",
                     challenge,
                     car1_response, car2_response, car3_response,
                     car4_response, car5_response);

            // Accumulate bias metrics
            total_ones_car1 = total_ones_car1 + count_ones(car1_response);
            total_ones_car2 = total_ones_car2 + count_ones(car2_response);
            total_ones_car3 = total_ones_car3 + count_ones(car3_response);
            total_ones_car4 = total_ones_car4 + count_ones(car4_response);
            total_ones_car5 = total_ones_car5 + count_ones(car5_response);

            // Accumulate inter-die Hamming distances for all 10 car pairs
            responses[0] = car1_response;
            responses[1] = car2_response;
            responses[2] = car3_response;
            responses[3] = car4_response;
            responses[4] = car5_response;

            for (pair_idx_a = 0; pair_idx_a < 4; pair_idx_a = pair_idx_a + 1) begin
                for (pair_idx_b = pair_idx_a + 1; pair_idx_b < 5; pair_idx_b = pair_idx_b + 1) begin
                    xor_result = responses[pair_idx_a] ^ responses[pair_idx_b];
                    hd_bits = count_ones(xor_result);
                    total_hd = total_hd + hd_bits;
                    pair_count = pair_count + 1;
                end
            end

            // Export CRP to CSV
            $fdisplay(csv_file, "%032h,%08h,%08h,%08h,%08h,%08h",
                      challenge,
                      car1_response, car2_response, car3_response,
                      car4_response, car5_response);
            $fflush(csv_file);

            // Deassert trigger
            trigger = 1'b0;
            #(RESET_TIME);
        end

        // ── Summary Report ────────────────────────────────────────────
        $display("---------------------------------|----------|----------|----------|----------|----------");
        $display("");
        $display("================================================================================");
        $display("  STATISTICAL ANALYSIS & PUF UNIQUENESS METRICS");
        $display("================================================================================");
        $display("  Total CRPs Evaluated          : %0d", NUM_CHALLENGES);
        $display("  Challenge Vector Width        : %0d bits", N);
        $display("  Response Vector Width         : %0d bits (generated in 1 clock cycle)", RESP_BITS);
        $display("");
        $display("  Inter-Die Hamming Distance (Uniqueness):");
        $display("    Car-pair combinations      : %0d evaluations (10 pairs x %0d challenges)", pair_count, NUM_CHALLENGES);
        $display("    Average Hamming Distance    : %0d.%02d bits / %0d bits",
                 total_hd / pair_count,
                 ((total_hd % pair_count) * 100) / pair_count,
                 RESP_BITS);
        $display("    Average Inter-Die HD (%%)    : %0d.%02d%% (Ideal Target: 50.00%%)",
                 (total_hd * 100) / (pair_count * RESP_BITS),
                 ((total_hd * 10000) / (pair_count * RESP_BITS)) % 100);
        $display("");
        $display("  Per-Car Response Uniformity / Bias (ones / total bits):");
        $display("    Car 1 (VID 101): %0d / %0d (%0d%%)",
                 total_ones_car1, NUM_CHALLENGES * RESP_BITS,
                 (total_ones_car1 * 100) / (NUM_CHALLENGES * RESP_BITS));
        $display("    Car 2 (VID 102): %0d / %0d (%0d%%)",
                 total_ones_car2, NUM_CHALLENGES * RESP_BITS,
                 (total_ones_car2 * 100) / (NUM_CHALLENGES * RESP_BITS));
        $display("    Car 3 (VID 103): %0d / %0d (%0d%%)",
                 total_ones_car3, NUM_CHALLENGES * RESP_BITS,
                 (total_ones_car3 * 100) / (NUM_CHALLENGES * RESP_BITS));
        $display("    Car 4 (VID 104): %0d / %0d (%0d%%)",
                 total_ones_car4, NUM_CHALLENGES * RESP_BITS,
                 (total_ones_car4 * 100) / (NUM_CHALLENGES * RESP_BITS));
        $display("    Car 5 (VID 105): %0d / %0d (%0d%%)",
                 total_ones_car5, NUM_CHALLENGES * RESP_BITS,
                 (total_ones_car5 * 100) / (NUM_CHALLENGES * RESP_BITS));
        $display("================================================================================");
        $display("");
        $display("  Output Files Verified:");
        $display("    [VCD] puf_fleet_waveform.vcd      (Pre-arbiter race signals exposed)");
        $display("    [CSV] ../data/puf_crp_export.csv  (32 CRPs for Python SNN pipeline)");
        $display("");
        $display("  GTKWave Visual Proof Instructions:");
        $display("    1. Open 'puf_fleet_waveform.vcd' in GTKWave");
        $display("    2. Under 'puf_fleet_tb', add signals:");
        $display("         - car1_lane0_upper  &  car1_lane0_lower  (Car 1 Lane 0 Race)");
        $display("         - car2_lane0_upper  &  car2_lane0_lower  (Car 2 Lane 0 Race)");
        $display("         - car1_response[31:0] & car2_response[31:0]");
        $display("    3. Zoom into the rising transition after trigger fires");
        $display("    4. Observe the picosecond delay difference between upper and lower edges!");
        $display("================================================================================");

        $fclose(csv_file);
        $finish;
    end

endmodule
